#!/bin/bash
# Rebuild the pinned GPL-3.0 HaGeZi Multi LIGHT snapshot without network access.
# --check compares generated bytes; --fetch restores only hash-pinned inputs.
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
mode=generate
fetch=false
for argument in "$@"; do
  case "$argument" in
    --check) mode=check ;;
    --fetch) fetch=true ;;
    *) echo "usage: Tools/make-blocklist.sh [--check] [--fetch]" >&2; exit 2 ;;
  esac
done
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
if [[ "$fetch" == true ]]; then
  python3 "$root/Tools/BlocklistSources/verify.py" --fetch --hosts-output "$work/hosts"
else
  python3 "$root/Tools/BlocklistSources/verify.py" --hosts-output "$work/hosts"
fi
swiftc -O "$root/Feather/Engine/BlocklistConverter.swift" "$root/Tools/MakeBlocklist/main.swift" -o "$work/make-blocklist"
"$work/make-blocklist" "$work/hosts" "$work/network.json"
python3 "$root/Tools/BlocklistSources/verify.py" --generated "$work/network.json"
if [[ "$mode" == check ]]; then
  cmp "$work/network.json" "$root/Feather/Resources/Blocklist/network.json"
  echo "Bundled blocklist matches the pinned offline build."
else
  cp "$work/network.json" "$root/Feather/Resources/Blocklist/network.json"
fi
